use super::*;
use crate::{coal_bag::Config as Bag,mining::{Config,Pickaxe,Rock},inventory::Item,loc_collision::LocCollision,stats::Stats,variables::{Varp,Varbit,Transmit}};
struct Draws(VecDeque<(u32,u32)>);impl RandomSource for Draws{fn below(&mut self,b:u32)->u32{let(k,v)=self.0.pop_front().expect("Unexpected coal mining RNG");assert_eq!(b,k);v}}
fn fixture(raw:i32,stored:i32,member:bool,cape:Option<i32>,product:i32)->(World,ActorId,Location){
 let mut w=World::default();for x in(3192..3216).step_by(8){for z in(3192..3216).step_by(8){w.collision.allocate(x,z,0);}}let at=CoordGrid::new(3201,3200,0).unwrap();let loc=Location::new(at,1,10,0).unwrap();let ty=LocCollision{width:1,length:1,block_walk:2,block_range:true,break_route_finding:false};w.location_types.insert(1,ty);w.location_types.insert(2,ty);w.locations.load(loc);crate::loc_collision::toggle(&mut w.collision,loc.coords,loc.shape,loc.angle,ty,true).unwrap();
 let bag=Bag{closed:12019,open:24480,coal:453,capes:[9795,9796,13280],base:Varp{id:65531,permanent:true,transmit:Transmit::Never,bit_protect:true,client_code:-1},stored:Varbit{base:65531,lsb:25,msb:30}};w.coal_bag=Some(bag);w.object_types.stackable.extend([12019,24480]);w.mining=Some(Config{skill:14,picks:[(1265,Pickaxe{level:1,animation:625,interval:2,members:false,fast_one_in:None})].into(),rocks:[(1,Rock{members:false,restore:None,level:1,product,product_name:"Coal".into(),xp:50.0,depleted:2,respawn:12,rates:(256,256)})].into(),full_sound:2277});
 let mut stats=Stats::default();stats.set_base(14,30);stats.set_current(14,30);let mut p=PlayerData::new(1,"Open coal bag miner".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);p.inventory.restore_slot(0,Some(Item{id:1265,count:1,vars:0})).unwrap();if raw>=0{p.inventory.restore_slot(27,Some(Item{id:raw,count:1,vars:0})).unwrap();}if let Some(id)=cape{p.equipment.restore_slot(1,Some(Item{id,count:1,vars:0})).unwrap();}p.variables.set(bag.base,0x81000001u32 as i32,false);p.variables.set_bit(bag.base,bag.stored,stored,false).unwrap();w.queue_login(1,p).unwrap();w.tick_with_random(&mut Draws(VecDeque::new())).unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();w.drain_events();(w,a,loc)
}
fn stored(w:&World,a:ActorId)->i32{w.data(a).unwrap().variables.bit(w.coal_bag.unwrap().stored).unwrap()}
fn mine(w:&mut World,a:ActorId,loc:Location)->Vec<crate::gathering::Trace>{w.submit(a,Action::OperateLocation{coords:loc.coords,id:loc.id,operation:1,control:false}).unwrap();let mut rng=Draws([(256,0),(255,0)].into());let mut traces=Vec::new();for _ in 0..6{w.tick_with_random(&mut rng).unwrap();traces.extend(w.drain_events().into_iter().filter_map(|e|if let WorldEvent::Mining{trace,..}=e{Some(trace)}else{None}));}assert!(rng.0.is_empty());traces}
#[test]
fn coal_bag_mining_open_closed_absent_full_member_and_worn_capacity_have_exact_conservation(){for raw in[24480,12019,-1]{for member in[false,true]{for cape in[None,Some(9795),Some(9796),Some(13280)]{for initial in[0,26,27,35,36]{let(mut w,a,loc)=fixture(raw,initial,member,cape,453);let before=w.data(a).unwrap().stats.fine_xp(14);let traces=mine(&mut w,a,loc);let success=traces.iter().filter(|t|t.result=="success").collect::<Vec<_>>();assert_eq!(success.len(),1);let capture=raw==24480&&member&&initial<if cape.is_some(){36}else{27};assert_eq!(stored(&w,a),initial+i32::from(capture));assert_eq!(success[0].stored_delta,i32::from(capture));assert_eq!(success[0].product_delta,i32::from(!capture));assert_eq!(w.data(a).unwrap().inventory.slots().iter().flatten().filter(|i|i.id==453).count(),usize::from(!capture));assert_eq!(w.data(a).unwrap().stats.fine_xp(14)-before,500);assert_eq!(w.data(a).unwrap().variables.get(65531)as u32&!(63<<25),0x81000001);let json=success[0].json(a,crate::gathering::Activity::Mining);assert_eq!(json.contains("\"stored_delta\":1"),capture);assert!(w.locations.find_type(loc.coords,2).is_some());}}}}}
#[test]
fn coal_bag_mining_preserves_source_full_inventory_refusal_even_with_storage_space(){let(mut w,a,loc)=fixture(24480,0,true,None,453);for slot in 1..27{w.data_mut(a).unwrap().inventory.restore_slot(slot,Some(Item{id:1511,count:1,vars:0})).unwrap();}let before=w.data(a).unwrap().clone();w.submit(a,Action::OperateLocation{coords:loc.coords,id:loc.id,operation:1,control:false}).unwrap();for _ in 0..4{w.tick_with_random(&mut Draws(VecDeque::new())).unwrap();}assert_eq!(stored(&w,a),0);assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().stats,before.stats);assert!(w.locations.find_type(loc.coords,1).is_some());assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::Mining{trace,..}if trace.result=="capacity"&&trace.roll.is_none())));}
#[test]
fn coal_bag_mining_failed_location_and_invalid_reward_do_not_commit_staged_storage_or_xp(){for footprint in[false,true]{let(mut w,a,mut loc)=fixture(24480,26,true,None,453);if footprint{
    loc=Location::new(CoordGrid::new(16383,3200,0).unwrap(),1,10,0).unwrap();w.locations.load(loc);w.collision.allocate(16376,3200,0);crate::loc_collision::toggle(&mut w.collision,loc.coords,10,0,w.location_types[&1],true).unwrap();w.location_types.get_mut(&2).unwrap().width=2;let p=w.players.get_mut(a.slot as usize).unwrap();p.movement.coords=CoordGrid::new(16382,3200,0).unwrap();p.data.coords=p.movement.coords;
    }else{w.object_types.dummy.insert(453);}let before=w.data(a).unwrap().clone();w.submit(a,Action::OperateLocation{coords:loc.coords,id:loc.id,operation:1,control:false}).unwrap();let mut rng=Draws(if footprint{[(256,0),(255,0)].into()}else{[(256,0)].into()});for _ in 0..5{w.tick_with_random(&mut rng).unwrap();}assert!(rng.0.is_empty());assert_eq!(stored(&w,a),26);assert_eq!(w.data(a).unwrap().inventory,before.inventory);assert_eq!(w.data(a).unwrap().stats,before.stats);}}
#[test]
fn coal_bag_mining_outfit_keeps_bonus_and_other_ores_ignore_storage(){for coal in[false,true]{let(mut w,a,loc)=fixture(24480,0,true,None,if coal{453}else{440});w.gathering_outfits.insert(14,crate::gathering_outfits::Outfit{members:true,pieces:vec![crate::gathering_outfits::Piece{slot:0,item_ids:vec![12013],basis_points:40}],full_set_basis_points:0});w.data_mut(a).unwrap().equipment.restore_slot(0,Some(Item{id:12013,count:1,vars:0})).unwrap();let before=w.data(a).unwrap().stats.fine_xp(14);let traces=mine(&mut w,a,loc);assert_eq!(w.data(a).unwrap().stats.fine_xp(14)-before,502);assert_eq!(stored(&w,a),i32::from(coal));assert_eq!(traces.iter().filter(|t|t.result=="success").map(|t|t.stored_delta).sum::<i32>(),i32::from(coal));}}
#[test]
fn coal_bag_mining_rechecks_current_open_form_membership_cape_and_single_bag_at_reward(){for case in 0..5{let(mut w,a,loc)=fixture(24480,if case==2{27}else{0},true,if case==2{Some(9795)}else{None},453);w.submit(a,Action::OperateLocation{coords:loc.coords,id:loc.id,operation:1,control:false}).unwrap();w.tick_with_random(&mut Draws(VecDeque::new())).unwrap();assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::Mining{trace,..}if trace.result=="scheduled")));match case{0=>{w.data_mut(a).unwrap().inventory.restore_slot(27,Some(Item{id:12019,count:1,vars:0})).unwrap();},1=>w.set_membership(a,false).unwrap(),2=>{w.data_mut(a).unwrap().equipment.restore_slot(1,None).unwrap();},3=>{w.data_mut(a).unwrap().inventory.restore_slot(27,Some(Item{id:24480,count:2,vars:0})).unwrap();},_=>{w.data_mut(a).unwrap().inventory.restore_slot(27,Some(Item{id:24480,count:1,vars:7})).unwrap();}}
    let initial=stored(&w,a);let mut rng=Draws([(256,0),(255,0)].into());for _ in 0..5{w.tick_with_random(&mut rng).unwrap();}assert!(rng.0.is_empty());assert_eq!(stored(&w,a),initial);assert_eq!(w.data(a).unwrap().inventory.slots().iter().flatten().filter(|i|i.id==453).count(),1);
}}
